WITH scored AS (SELECT id, device, country, ROW_NUMBER() OVER (ORDER BY started_at DESC, id) AS event_seq, LAST_VALUE(country) IGNORE NULLS OVER (PARTITION BY browser ORDER BY started_at, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS last_known_country FROM sessions WHERE browser <> 'Safari') SELECT CASE WHEN event_seq >= 8 THEN 'PREMIUM' ELSE 'STANDARD' END AS event_seq_tier, device, COUNT(*) AS num_rows, SUM(event_seq) FILTER (WHERE device = 'mobile') AS mobile_total_event_seq, ROUND(SUM(event_seq) / NULLIF(COUNT(CASE WHEN device = 'tablet' THEN 1 END), 0), 2) AS event_seq_per_tablet, ROUND(SUM(event_seq) / NULLIF(COUNT(CASE WHEN device = 'desktop' THEN 1 END), 0), 2) AS event_seq_per_desktop, GROUPING(CASE WHEN event_seq >= 8 THEN 'PREMIUM' ELSE 'STANDARD' END) AS grouping_level FROM scored GROUP BY ROLLUP (CASE WHEN event_seq >= 8 THEN 'PREMIUM' ELSE 'STANDARD' END, device) HAVING ROUND(SUM(event_seq) / NULLIF(COUNT(CASE WHEN device = 'desktop' THEN 1 END), 0), 2) >= 0 ORDER BY mobile_total_event_seq DESC NULLS LAST
